//! Rollout metrics for learners on physics (plan P6).
//!
//! bits per byte says how well a learner *codes* a trajectory. A rollout asks
//! whether it can *predict* one. The header and the first [`CONTEXT`] timesteps
//! of a held-out trajectory are given; the learner then generates [`HORIZON`]
//! more timesteps, one byte at a time, taking the most probable byte each time
//! (greedy argmax, so the rollout is deterministic). The generated bytes are
//! decoded, and each predicted state is compared with the true one.
//!
//! ## The encoding is `i32`, and only `i32`
//!
//! Rollouts run on the [`Encoding::I32`] layout, where each timestep is written
//! before the next. Under [`Encoding::Planes`] the byte-planes are laid out
//! across the whole trajectory, so byte `k` of step `t` cannot be known until
//! every step has been generated. A planes prefix holds no whole timestep, so
//! it cannot be rolled out step by step. (`coarse` and `diff2` could be rolled
//! out, since both are causal in the stream, but plan P6 specifies `i32`, and
//! they are not measured here.)
//!
//! ## What is measured
//!
//! * **State error** at horizons 1, 10 and 100: the RMS, over the trajectories,
//!   of the root-mean-square error over channels, in the system's units.
//!   Angle channels are compared on the circle, so `π − ε` and `−π + ε` are
//!   `2ε` apart. The channels mix units (angles, rates, positions, velocities),
//!   so the figure is a scale, not a single physical quantity.
//! * **Energy drift** over the generated steps: the largest `|E_n − E_0| / |E_0|`
//!   by [`physics::energy`], where `E_0` is the true initial energy. Measured
//!   only for systems whose energy is conserved (pendulum, double pendulum and
//!   n-body). The damped spring and the inelastic bounce lose energy by design,
//!   so there is no drift to measure.
//! * **Two trivial baselines** on the same contexts. *Hold* repeats the last
//!   given state. *Constant velocity* extrapolates the last given state along
//!   the last given step. A learner is said to beat the trivial baseline at a
//!   horizon when its error is below the smaller of the two.
//!
//! Energy conservation alone does not mean prediction: holding a state
//! conserves energy exactly, so *hold* has near-zero drift on a conservative
//! system. The drift column is read with the error columns, not on its own.

use crate::learner::{ByteLearner, Predictor};
use crate::physics::{self, Encoding, Params, ParamRange, State, System};

/// Timesteps given before generation starts, after the header.
pub const CONTEXT: usize = 10;
/// Timesteps generated per rollout.
pub const HORIZON: usize = 100;
/// The horizons reported, in timesteps ahead of the context.
pub const HORIZONS: [usize; 3] = [1, 10, 100];

/// Whether the system's energy is conserved, and so has a drift to measure.
pub fn conserves_energy(system: System) -> bool {
    matches!(system, System::Pendulum | System::DoublePendulum | System::NBody)
}

/// The index of the largest value, the first one on a tie.
fn argmax(p: &[f64; 256]) -> usize {
    let mut best = 0;
    for (y, &v) in p.iter().enumerate() {
        if v > p[best] {
            best = y;
        }
    }
    best
}

/// Generates `n` bytes after `prefix`, each the most probable byte under the
/// learner's predictor at that point. Fails if the learner has no predictor.
pub fn generate_greedy(learner: &dyn ByteLearner, prefix: &[u8], n: usize) -> Result<Vec<u8>, String> {
    let mut p: Box<dyn Predictor + '_> = learner
        .predictor()
        .ok_or_else(|| format!("{} cannot generate one byte at a time", learner.describe()))?;
    for &b in prefix {
        p.push(b);
    }
    let mut out = Vec::with_capacity(n);
    for _ in 0..n {
        let b = argmax(&p.distribution()) as u8;
        p.push(b);
        out.push(b);
    }
    Ok(out)
}

/// Mean over channels of the squared error between two states, with angle
/// channels compared on the circle.
fn mean_square(system: System, predicted: &[f64], truth: &[f64]) -> f64 {
    let angles = system.angle_channels();
    let sum: f64 = predicted
        .iter()
        .zip(truth)
        .enumerate()
        .map(|(c, (&a, &b))| {
            let d = if angles.contains(&c) { physics::wrap_angle(a - b) } else { a - b };
            d * d
        })
        .sum();
    sum / predicted.len() as f64
}

/// The largest relative energy drift of `states` from `states[0]`'s energy, or
/// `None` when that energy is zero or not finite, or the system does not
/// conserve energy.
fn drift(system: System, params: &Params, states: &[State]) -> Option<f64> {
    if !conserves_energy(system) {
        return None;
    }
    let e0 = physics::energy(params, &states[0]);
    if e0 == 0.0 || !e0.is_finite() {
        return None;
    }
    Some(physics::energy_drift(params, states))
}

/// One rollout's figures. The `_sq` arrays hold the mean-square error over
/// channels at each of [`HORIZONS`]; [`Cell`] takes the root over trajectories.
#[derive(Debug, Clone, PartialEq)]
pub struct Outcome {
    pub learner_sq: [f64; 3],
    pub hold_sq: [f64; 3],
    pub cv_sq: [f64; 3],
    pub learner_drift: Option<f64>,
    pub hold_drift: Option<f64>,
    pub cv_drift: Option<f64>,
}

/// Rolls `learner` forward over one encoded `i32` trajectory of exactly
/// `CONTEXT + HORIZON` timesteps (or more). The first `CONTEXT` timesteps and the
/// header are given; the next `HORIZON` are generated and scored against the truth.
pub fn rollout_one(learner: &dyn ByteLearner, trajectory: &[u8]) -> Result<Outcome, String> {
    let (system, params, _quantum, truth) = physics::decode_prefix(trajectory)?;
    if truth.len() < CONTEXT + HORIZON {
        return Err(format!("trajectory has {} timesteps, needs {}", truth.len(), CONTEXT + HORIZON));
    }
    let ch = system.channels();
    let prefix_len = physics::header_len(system) + CONTEXT * ch * 4;
    let generated = generate_greedy(learner, &trajectory[..prefix_len], HORIZON * ch * 4)?;
    let mut full = trajectory[..prefix_len].to_vec();
    full.extend_from_slice(&generated);
    let (_, _, _, decoded) = physics::decode_prefix(&full)?;
    let predicted = &decoded[CONTEXT..];

    let last = &truth[CONTEXT - 1];
    let velocity: Vec<f64> = last.iter().zip(&truth[CONTEXT - 2]).map(|(a, b)| a - b).collect();
    let hold: Vec<State> = vec![last.clone(); HORIZON];
    let cv: Vec<State> = (1..=HORIZON)
        .map(|k| last.iter().zip(&velocity).map(|(x, v)| x + k as f64 * v).collect())
        .collect();

    let at = |h: usize| h - 1;
    let sq = |states: &[State]| HORIZONS.map(|h| mean_square(system, &states[at(h)], &truth[CONTEXT + at(h)]));
    // The drift reference is the true initial state, so each rollout is judged
    // against the system's own energy.
    let with_start = |states: &[State]| -> Vec<State> {
        let mut v = Vec::with_capacity(states.len() + 1);
        v.push(truth[0].clone());
        v.extend_from_slice(states);
        v
    };
    Ok(Outcome {
        learner_sq: sq(predicted),
        hold_sq: sq(&hold),
        cv_sq: sq(&cv),
        learner_drift: drift(system, &params, &with_start(predicted)),
        hold_drift: drift(system, &params, &with_start(&hold)),
        cv_drift: drift(system, &params, &with_start(&cv)),
    })
}

/// One system and learner, over a set of held-out trajectories.
#[derive(Debug, Clone, PartialEq)]
pub struct Cell {
    pub system: System,
    pub learner: String,
    pub trajectories: usize,
    /// RMS state error of the learner at each of [`HORIZONS`].
    pub learner_rms: [f64; 3],
    pub hold_rms: [f64; 3],
    pub cv_rms: [f64; 3],
    /// Mean over trajectories of the largest relative energy drift. `None` for
    /// systems without a conserved energy.
    pub learner_drift: Option<f64>,
    pub hold_drift: Option<f64>,
    pub cv_drift: Option<f64>,
}

impl Cell {
    /// For each horizon, whether the learner's error is below the smaller of the
    /// two trivial baselines' errors.
    pub fn beats_trivial(&self) -> [bool; 3] {
        let mut out = [false; 3];
        for (i, o) in out.iter_mut().enumerate() {
            *o = self.learner_rms[i] < self.hold_rms[i].min(self.cv_rms[i]);
        }
        out
    }
}

fn mean_of(values: &[Option<f64>]) -> Option<f64> {
    let present: Vec<f64> = values.iter().flatten().copied().collect();
    if present.is_empty() {
        None
    } else {
        Some(present.iter().sum::<f64>() / present.len() as f64)
    }
}

/// Rolls `learner` out on `trajectories` held-out trajectories of `system`,
/// drawn from [`ParamRange::HeldOut`] with `seed`, and aggregates the figures.
pub fn run_rollouts(learner: &dyn ByteLearner, system: System, seed: u64, trajectories: usize) -> Result<Cell, String> {
    let bytes = physics::corpus_as(system, ParamRange::HeldOut, seed, trajectories, CONTEXT + HORIZON, Encoding::I32);
    let mut outcomes = Vec::with_capacity(trajectories);
    let mut at = 0;
    while at < bytes.len() {
        let len = physics::encoded_len(&bytes[at..])?;
        outcomes.push(rollout_one(learner, &bytes[at..at + len])?);
        at += len;
    }
    let n = outcomes.len() as f64;
    let rms = |pick: fn(&Outcome) -> [f64; 3]| -> [f64; 3] {
        let mut out = [0.0; 3];
        for o in &outcomes {
            for (i, v) in pick(o).iter().enumerate() {
                out[i] += v / n;
            }
        }
        out.map(f64::sqrt)
    };
    Ok(Cell {
        system,
        learner: learner.describe(),
        trajectories: outcomes.len(),
        learner_rms: rms(|o| o.learner_sq),
        hold_rms: rms(|o| o.hold_sq),
        cv_rms: rms(|o| o.cv_sq),
        learner_drift: mean_of(&outcomes.iter().map(|o| o.learner_drift).collect::<Vec<_>>()),
        hold_drift: mean_of(&outcomes.iter().map(|o| o.hold_drift).collect::<Vec<_>>()),
        cv_drift: mean_of(&outcomes.iter().map(|o| o.cv_drift).collect::<Vec<_>>()),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::learner::{EntropyConfig, LearnerConfig, LearnerSpec, SsmConfig};

    /// A learner that always predicts the true next byte of `truth`, optionally
    /// with the byte at `perturb` (a stream index) flipped in its lowest bit.
    struct Oracle {
        truth: Vec<u8>,
        perturb: Option<usize>,
    }

    struct OraclePredictor<'a> {
        oracle: &'a Oracle,
        at: usize,
    }

    impl Predictor for OraclePredictor<'_> {
        fn distribution(&self) -> [f64; 256] {
            let mut d = [0.0; 256];
            let mut y = self.oracle.truth.get(self.at).copied().unwrap_or(0) as usize;
            if self.oracle.perturb == Some(self.at) {
                y ^= 1;
            }
            d[y] = 1.0;
            d
        }
        fn push(&mut self, _byte: u8) {
            self.at += 1;
        }
    }

    impl ByteLearner for Oracle {
        fn bits_per_byte(&self, _bytes: &[u8]) -> f64 {
            0.0
        }
        fn progress(&self, _bytes: &[u8]) -> f64 {
            0.0
        }
        fn train(&mut self, _batch: &[&[u8]]) {}
        fn parameters(&self) -> usize {
            0
        }
        fn bytes_seen(&self) -> u64 {
            0
        }
        fn describe(&self) -> String {
            "oracle".into()
        }
        fn predictor(&self) -> Option<Box<dyn Predictor + '_>> {
            Some(Box::new(OraclePredictor { oracle: self, at: 0 }))
        }
    }

    /// A learner with no predictor: it can code bytes but not generate them.
    struct Mute;

    impl ByteLearner for Mute {
        fn bits_per_byte(&self, _bytes: &[u8]) -> f64 {
            8.0
        }
        fn progress(&self, _bytes: &[u8]) -> f64 {
            0.0
        }
        fn train(&mut self, _batch: &[&[u8]]) {}
        fn parameters(&self) -> usize {
            0
        }
        fn bytes_seen(&self) -> u64 {
            0
        }
        fn describe(&self) -> String {
            "mute".into()
        }
    }

    /// One held-out trajectory of `system`, of exactly `CONTEXT + HORIZON` steps.
    fn held_out(system: System, seed: u64) -> Vec<u8> {
        physics::corpus_as(system, ParamRange::HeldOut, seed, 1, CONTEXT + HORIZON, Encoding::I32)
    }

    /// A small n-gram, trained for a few steps on pendulum trajectories so its
    /// distributions are not uniform.
    fn trained_ngram() -> Box<dyn ByteLearner> {
        let spec = LearnerSpec::Ngram(LearnerConfig { orders: 2, log2_buckets: 8, lr: 0.05 });
        physics::physics_train(System::Pendulum, spec, physics::BASELINE_CHUNK * physics::BASELINE_BATCH * 10, 200, 1, Encoding::I32)
            .expect("trains")
    }

    /// The bits per byte of `bytes` as the predictor scores them, for checking
    /// that the accessor is the distribution `bits_per_byte` computes.
    fn nll_through_predictor(learner: &dyn ByteLearner, bytes: &[u8]) -> f64 {
        let mut p = learner.predictor().expect("has a predictor");
        let mut nll = 0.0;
        for &b in bytes {
            nll -= p.distribution()[b as usize].max(1e-300).log2();
            p.push(b);
        }
        nll / bytes.len() as f64
    }

    #[test]
    fn each_predictor_scores_bytes_as_its_learner_does() {
        let bytes = physics::corpus_as(System::Spring, ParamRange::Train, 2, 1, 60, Encoding::I32);
        let specs = [
            LearnerSpec::Ngram(LearnerConfig { orders: 3, log2_buckets: 8, lr: 0.05 }),
            LearnerSpec::Entropy(EntropyConfig { orders: 2, log2_buckets: 8, target_len: 4.0, lr: 0.05 }),
            LearnerSpec::Ssm(SsmConfig { d: 4, lr: 0.05, bptt: 16 }),
        ];
        for spec in specs {
            let mut learner = crate::learner::build(spec).expect("builds");
            // A few train steps, so the distributions are not uniform.
            for chunk in bytes.chunks(200).take(3) {
                learner.train(&[chunk]);
            }
            let want = learner.bits_per_byte(&bytes[..120]);
            let got = nll_through_predictor(learner.as_ref(), &bytes[..120]);
            assert!((want - got).abs() < 1e-9, "{}: bits_per_byte {want} vs predictor {got}", learner.describe());
        }
    }

    #[test]
    fn a_perfect_rollout_has_zero_error_at_every_horizon() {
        for system in [System::Pendulum, System::NBody] {
            let traj = held_out(system, 3);
            let oracle = Oracle { truth: traj.clone(), perturb: None };
            let out = rollout_one(&oracle, &traj).expect("rolls out");
            assert_eq!(out.learner_sq, [0.0; 3], "{}", system.name());
            let drift = out.learner_drift.expect("conserves energy");
            assert!(drift.is_finite() && drift < 1e-2, "{}: drift {drift}", system.name());
            assert!(out.hold_sq.iter().all(|v| v.is_finite() && *v > 0.0), "{}", system.name());
        }
    }

    #[test]
    fn the_error_at_each_horizon_is_read_at_its_own_step() {
        // Flip the lowest bit of channel 0 at one generated step. Only the
        // horizon that reads that step may see error: horizon h reads step
        // CONTEXT + h - 1, so k = 0, 9 and 99 hit horizons 1, 10 and 100, and k = 5
        // hits none of them.
        let system = System::Pendulum;
        let traj = held_out(system, 3);
        let hl = physics::header_len(system);
        let ch = system.channels();
        for (k, hit) in [(0usize, Some(0usize)), (9, Some(1)), (99, Some(2)), (5, None)] {
            let stream = hl + (CONTEXT + k) * ch * 4;
            let oracle = Oracle { truth: traj.clone(), perturb: Some(stream) };
            let out = rollout_one(&oracle, &traj).expect("rolls out");
            for (i, &v) in out.learner_sq.iter().enumerate() {
                if Some(i) == hit {
                    assert!(v > 0.0, "step +{k}: horizon {} should see the flip", HORIZONS[i]);
                } else {
                    assert_eq!(v, 0.0, "step +{k}: horizon {} should not see it", HORIZONS[i]);
                }
            }
        }
    }

    #[test]
    fn a_trivial_baseline_has_finite_nonzero_error_on_held_out_physics() {
        let learner = trained_ngram();
        let cell = run_rollouts(learner.as_ref(), System::Pendulum, 1, 4).expect("runs");
        for v in cell.hold_rms.iter().chain(&cell.cv_rms).chain(&cell.learner_rms) {
            assert!(v.is_finite() && *v > 0.0, "{v}");
        }
        assert!(cell.learner_drift.is_some() && cell.cv_drift.is_some());
    }

    #[test]
    fn no_drift_is_reported_for_a_system_that_does_not_conserve_energy() {
        let learner = trained_ngram();
        for system in [System::Spring, System::Bounce] {
            let cell = run_rollouts(learner.as_ref(), system, 1, 2).expect("runs");
            assert_eq!((cell.learner_drift, cell.hold_drift, cell.cv_drift), (None, None, None), "{}", system.name());
        }
    }

    #[test]
    fn rollouts_are_deterministic() {
        let learner = trained_ngram();
        let a = run_rollouts(learner.as_ref(), System::DoublePendulum, 2, 3).expect("runs");
        let b = run_rollouts(learner.as_ref(), System::DoublePendulum, 2, 3).expect("runs");
        assert_eq!(a, b);
        let traj = held_out(System::DoublePendulum, 2);
        let g1 = generate_greedy(learner.as_ref(), &traj[..20], 40).expect("generates");
        let g2 = generate_greedy(learner.as_ref(), &traj[..20], 40).expect("generates");
        assert_eq!(g1, g2);
    }

    #[test]
    fn a_learner_without_a_predictor_is_refused_not_scored() {
        let traj = held_out(System::Pendulum, 1);
        let err = rollout_one(&Mute, &traj).expect_err("cannot generate");
        assert!(err.contains("cannot generate"), "{err}");
    }
}
